import {icon} from './icons.js';
import {weekDays,slotCapacity,today,addDays,moveMonth,monthCells,minuteLabel,isoAt,summary,statusNames,escapeHTML as h,sampleData} from './domain.js';
const root=document.querySelector('#app'),modal=document.querySelector('#modal');
const cfg=window.CONNECT_CONFIG;
const db=cfg?.url&&cfg?.key?window.supabase.createClient(cfg.url,cfg.key,{auth:{storageKey:'connect-owner-web-auth',detectSessionInUrl:false}}):null;
const state={demo:false,user:null,store:null,rows:[],events:[],blocks:[],day:today(),month:today().slice(0,7),view:'ledger',page:'dashboard',filter:'all',query:'',selected:null,error:'',eventError:'',loaded:false,lastSync:null,loading:false,busy:false,epoch:0,large:false,scope:'today',loadedRange:null,selectedSlot:null,slotReservation:null};
let authEmail='',authSent=false,authBusy=false,authError='',resendAfter=0,requestKey=null,lastPayload='',pendingRefresh=false;
const brand=()=>'<div class="brand"><span class="brand-mark">↗</span>Connect<em>BIZ</em></div>';
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const themeButton=()=>btn('', 'theme', 'ghost theme-toggle', 'aria-label="다크모드"');
function syncThemeButtons(){const dark=document.documentElement.dataset.theme==='dark';document.querySelectorAll('[data-action=theme]').forEach(b=>{b.innerHTML=icon(dark?'sun':'moon')+`<span>${dark?'라이트모드':'다크모드'}</span>`;b.setAttribute('aria-label',dark?'라이트모드로 전환':'다크모드로 전환');});}
document.addEventListener('connect-theme-change',syncThemeButtons);
new MutationObserver(syncThemeButtons).observe(root,{childList:true});
const badge=r=>`<span class="tag ${r.status}">${statusNames[r.status]||h(r.status)}</span>`;
const dateTitle=day=>new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'short',timeZone:'Asia/Seoul'}).format(new Date(day+'T12:00:00+09:00'));
const monthTitle=()=>`${Number(state.month.slice(0,4))}년 ${Number(state.month.slice(5))}월`;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500);}
function message(e){if(!navigator.onLine)return '인터넷 연결을 확인해주세요. 저장 결과를 다시 확인한 후 재시도하세요.';return e?.message||'요청을 처리하지 못했습니다. 다시 시도해주세요.';}
function login(){root.innerHTML=`<main class="login-shell"><section class="login-art">${brand()}<div class="login-copy"><p class="eyebrow">YOUR DAY, CONNECTED</p><h1>예약부터 하루 일정까지,<br>한눈에 연결하세요.</h1><p>앱으로 받은 예약도, 전화로 받은 예약도.<br>사장님의 하루를 담는 하나의 예약 장부.</p><div class="mini-ledger"><div class="inline" style="justify-content:space-between"><strong>오늘의 예약</strong><span class="tag confirmed">12명 방문 예정</span></div><div class="mini-row"><span>17:30 &nbsp; 박지현 · 4명</span><span class="tag confirmed">예약 확정</span></div><div class="mini-row"><span>18:30 &nbsp; 학생회 · 20명</span><span class="tag pending">승인 대기</span></div><div class="mini-row"><span>20:00 &nbsp; 스터디 · 8명</span><span class="tag confirmed">예약 확정</span></div></div></div><small class="muted">예약에 쓰던 시간을, 손님에게.</small></section><section class="login-form-area"><div class="login-card"><div class="login-theme">${themeButton()}</div><p class="eyebrow">OWNER WORKSPACE</p><a href="./">← 이용 유형 선택</a><h1>점주 로그인</h1><p>Connect 앱에서 사용하는 이메일로 시작하세요.</p><form id="login-form"><label class="field">이메일<input name="email" type="email" autocomplete="email" placeholder="owner@example.com" value="${h(authEmail)}" required ${authBusy?'disabled':''}></label>${authSent?`<label class="field">인증번호<input name="token" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6,10}" minlength="6" maxlength="10" placeholder="메일로 받은 인증번호" required></label><p class="form-note">${h(authEmail)}로 인증 메일을 요청했습니다. 메일함을 확인해주세요.</p>`:''}<p class="form-error" role="alert">${h(authError)}</p><button class="primary" ${authBusy||!db?'disabled':''}>${authBusy?'처리 중…':authSent?'인증하고 로그인':'인증번호 받기'}</button>${authSent?btn('다른 이메일 / 인증번호 재요청','auth-reset','ghost'):''}</form><p class="small muted">신규 가입과 매장 등록은 Connect 앱에서 진행해주세요.</p><hr style="border:0;border-top:1px solid var(--line);margin:27px 0">${btn('샘플 매장으로 둘러보기 →','demo','secondary')}<p class="small muted">샘플 데이터로 화면을 체험할 수 있습니다. 실제 예약에는 반영되지 않습니다.</p>${!db?'<p class="form-error">서버 연결 설정이 없습니다. 공개 클라이언트 설정을 확인해주세요.</p>':''}</div></section></main>`;}
function dayRows(){return state.rows.filter(r=>r.service_date===state.day).sort((a,b)=>a.start_minute-b.start_minute);}
function visibleRows(){
  if(state.page==='reservations')return state.rows.filter(r=>r.status==='pending').sort((a,b)=>(b.created_at||b.starts_at).localeCompare(a.created_at||a.starts_at));
  if(state.page==='dashboard'){const days=state.scope==='today'?[state.day]:weekDays(state.day);return state.rows.filter(r=>r.status==='confirmed'&&days.includes(r.service_date)).sort((a,b)=>a.starts_at.localeCompare(b.starts_at));}
  return dayRows();
}
function filteredRows(){return visibleRows().filter(r=>(state.page!=='calendar'||state.filter==='all'||r.status===state.filter)&&`${r.booker_name} ${r.booker_affiliation||''}`.toLowerCase().includes(state.query.toLowerCase()));}
function table(){const rows=filteredRows();return rows.length?`<div class="table-scroll"><table><thead><tr><th>예약일 · 시간</th><th>대표 예약자 / 소속·단체</th><th class="num">인원</th><th>상태</th></tr></thead><tbody>${rows.map(r=>`<tr class="${state.selected===r.id?'selected':''}"><td>${state.page!=='calendar'?`<small class="row-date">${dateTitle(r.service_date)}</small>`:''}<strong>${minuteLabel(r.start_minute)}</strong><small>~ ${minuteLabel(r.start_minute+r.slot_count*30)}</small></td><td><button class="row-name" data-action="select" data-id="${h(r.id)}" aria-label="${h(r.booker_name)} 예약 상세"><strong>${h(r.booker_name)}</strong><small>${h(r.booker_affiliation||'소속·단체 없음')} · ${r.is_manual?'직접 등록':'Connect'}</small></button></td><td class="num">${r.people}명</td><td>${badge(r)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><span class="empty-mark">▤</span>${state.loading&&!state.loaded?'예약을 불러오고 있습니다…':state.error&&!state.loaded?'예약을 불러오지 못했습니다. 위의 다시 새로고침을 눌러주세요.':state.query?'검색 조건에 맞는 예약이 없습니다.':state.page==='reservations'?'처리할 예약 요청이 없습니다.':state.page==='dashboard'?'이 기간에 확정된 예약이 없습니다.':'이 날짜에는 예약이 없습니다.'}<br><small>${state.page==='reservations'?'새로운 예약 요청이 들어오면 여기에 표시됩니다.':'전화·문자 예약은 ‘예약 등록’으로 추가하세요.'}</small></div>`;}
function detail(id=state.selected){const r=state.rows.find(r=>r.id===id);if(!r)return '<div class="empty"><span class="empty-mark">↖</span>예약을 선택해주세요.<br><small>예약 내용과 요청사항을<br>확인할 수 있습니다.</small></div>';const now=Date.now();return `<div class="detail"><div class="detail-head"><h3>예약 상세</h3>${badge(r)}</div><h2>${h(r.booker_name)}</h2><p class="source">${r.is_manual?'직접 등록한 예약':'Connect 앱에서 접수한 예약'}</p><dl><dt>대표 예약자</dt><dd>${h(r.booker_name)}</dd><dt>예약일</dt><dd>${dateTitle(r.service_date)}</dd><dt>이용 시간</dt><dd>${minuteLabel(r.start_minute)}<br>~ ${minuteLabel(r.start_minute+r.slot_count*30)}</dd><dt>방문 인원</dt><dd><strong>${r.people}명</strong></dd><dt>소속 / 단체</dt><dd>${h(r.booker_affiliation||'—')}</dd><dt>예약 목적</dt><dd>${h(r.event_purpose||'—')}</dd></dl><h3 style="margin-bottom:10px">요청사항</h3><div class="memo">${h(r.request_message||'등록된 요청사항이 없습니다.')}</div><div class="detail-actions">${r.status==='pending'?`${btn('거절','reject','',`data-id="${h(r.id)}" ${state.busy?'disabled':''}`)}${btn('예약 수락','accept','primary',`data-id="${h(r.id)}" ${state.busy?'disabled':''}`)}`:''}${['confirmed','pending'].includes(r.status)&&new Date(r.starts_at).getTime()>now?btn('예약 취소','cancel','danger',`data-id="${h(r.id)}" ${state.busy?'disabled':''}`):''}${r.status==='confirmed'&&new Date(r.ends_at).getTime()<=now?btn('이용 완료','complete','primary',`data-id="${h(r.id)}" ${state.busy?'disabled':''}`):''}</div><p class="detail-foot">${r.status==='pending'?'수락하면 확정 예약에 반영됩니다. 잔여 좌석은 수락 시 다시 확인합니다.':'변경 사항은 Connect 앱에도 함께 반영됩니다.'}</p></div>`;}
function calendar(){return `<div class="calendar">${['일','월','화','수','목','금','토'].map(d=>`<div class="weekday">${d}</div>`).join('')}${monthCells(state.month).map(day=>{const s=summary(state.rows.filter(r=>r.service_date===day)),ev=state.events.filter(e=>e.service_date===day);return `<button class="calendar-day ${day.startsWith(state.month)?'':'outside'} ${day===state.day?'chosen':''}" data-action="day" data-day="${day}" aria-label="${day} 확정 ${s.confirmed}건 ${s.people}명 대기 ${s.pending}건 일정 ${ev.length}건" aria-pressed="${day===state.day}"><span class="day-number">${Number(day.slice(8))}${day===today()?'<small>오늘</small>':''}</span>${s.confirmed?`<span class="cal-confirm">확정 ${s.confirmed} · ${s.people}명</span>`:''}${s.pending?`<span class="cal-pending">대기 ${s.pending}건</span>`:''}${ev.length?`<span class="cal-event">• ${h(ev[0].title)}${ev.length>1?` 외 ${ev.length-1}`:''}</span>`:''}</button>`;}).join('')}</div><div class="day-list-title">${dateTitle(state.day)} <span class="muted small">· 예약 ${dayRows().length}건</span></div>`;}
function schedules(){const events=state.events.filter(e=>e.service_date===state.day).sort((a,b)=>(a.start_minute??-1)-(b.start_minute??-1));const blocks=state.blocks.filter(b=>b.service_date===state.day);return `<section class="panel schedule"><div class="panel-top"><h2>매장 일정 <span class="muted small">${events.length}</span></h2>${btn('＋ 일정 추가','new-event','ghost small')}</div>${state.eventError?`<div class="notice error">${h(state.eventError)}</div>`:events.length?events.map(e=>`<div class="schedule-item"><span class="schedule-time">${e.start_minute===null?'종일':minuteLabel(e.start_minute)}</span><i class="schedule-dot"></i><div class="schedule-copy"><strong>${h(e.title)}</strong>${e.memo?`<small>${h(e.memo)}</small>`:''}</div>${btn('수정','edit-event','ghost',`data-id="${h(e.id)}"`)}</div>`).join(''):'<div class="empty" style="padding:23px">등록된 내부 일정이 없습니다.</div>'}<div class="schedule-item"><span class="schedule-dot" style="background:#bbb"></span><div class="schedule-copy small muted">예약 차단 ${blocks.length}개 시간대 · 내부 일정은 예약을 차단하지 않습니다.</div>${btn('시간 차단','blocks','ghost')}</div></section>`;}
function settings(){const s=state.store;return `<section class="panel settings"><h2>예약 운영 설정</h2><p class="muted small">Connect 앱과 같은 매장 설정을 사용합니다.</p><form id="settings-form"><label class="field">매장 최대 수용 인원<input name="capacity" type="number" min="1" max="10000" value="${s.capacity}" required></label><div class="form-grid"><label class="field">영업 시작<select name="opening">${timeOptions(s.opening_minute,0,1410)}</select></label><label class="field">영업 종료<select name="closing">${timeOptions(s.closing_minute,30,1800)}</select></label></div><label class="check-label"><input type="checkbox" name="shared" ${s.allow_shared?'checked':''}>정원 내 여러 팀 동시 예약 허용</label><p class="form-note">이미 확정된 예약을 수용할 수 없는 변경은 저장되지 않습니다.</p><p class="form-error" role="alert"></p><button class="primary" ${state.busy?'disabled':''}>설정 저장</button></form></section>`;}
function searchField(){return `<input id="search" type="search" placeholder="예약자 · 단체 검색" value="${h(state.query)}" aria-label="예약 검색">`;}
function weekReady(){const days=weekDays(state.day);return state.demo||(state.loadedRange&&state.loadedRange.first<=addDays(days[0],-1)&&state.loadedRange.next>addDays(days[6],1));}
function timetable(){const days=weekDays(state.day);const ready=weekReady();return `<section class="panel timetable-panel"><div class="panel-top"><div><h2>주간 예약 가능 시간</h2><p class="small muted" style="margin:7px 0 0">30분 단위 · 월요일부터 일요일까지</p></div><div class="inline">${btn('‹','week-prev','','aria-label="이전 주"')}${btn('이번 주','week-today','small')}${btn('›','week-next','','aria-label="다음 주"')}</div></div><div class="week-legend"><span><i class="swatch empty"></i>아예 빔</span><span><i class="swatch partial"></i>일부 예약 · 빈자리 있음</span><span><i class="swatch full"></i>예약 불가</span><span><i class="swatch past"></i>지난 시간</span></div><p class="week-caption">${dateTitle(days[0])} – ${dateTitle(days[6])} · 정원 ${state.store.capacity}명 · ${state.store.allow_shared?'여러 팀 동시 예약':'한 팀 단독 예약'}</p>${!ready?'<div class="empty">시간표 데이터를 불러오는 중입니다.</div>':`<div class="timetable-scroll"><table class="timetable"><thead><tr><th scope="col">시간</th>${days.map(d=>`<th scope="col" class="${d===today()?'is-today':''}">${dateTitle(d)}${d===today()?'<small>오늘</small>':''}</th>`).join('')}</tr></thead><tbody>${Array.from({length:(state.store.closing_minute-state.store.opening_minute)/30},(_,i)=>state.store.opening_minute+i*30).map(min=>`<tr><th scope="row">${minuteLabel(min)}</th>${days.map(day=>{const c=slotCapacity(state.store,state.rows,state.blocks,day,min);return `<td><button class="time-slot ${c.level} ${c.past?'past':c.blocked?'unavailable':''} ${state.selectedSlot?.day===day&&state.selectedSlot?.minute===min?'slot-selected':''}" data-action="slot-detail" data-day="${day}" data-minute="${min}" aria-label="${dateTitle(day)} ${minuteLabel(min)} ${c.reason}, 잔여 ${c.remaining}명"><span>${c.level==='empty'?'여유':c.level==='partial'?`잔여 ${c.remaining}명`:c.reason}</span></button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`}<p class="week-caption">셀을 누르면 예약과 잔여 인원을 확인할 수 있습니다. 승인 대기는 좌석을 차지하지 않습니다.<br>지난 시간은 회색으로, 점주 차단·단독 예약은 ‘예약 불가’로 표시합니다. 실제 접수 시 잔여 좌석을 다시 확인합니다.</p></section>`;}
function slotPanel(){
  if(state.selectedSlot&&!weekDays(state.day).includes(state.selectedSlot.day)){state.selectedSlot=null;state.slotReservation=null;}
  if(!state.selectedSlot)return '<div class="detail"><h2>시간대 상세</h2><p class="muted small">시간표의 칸을 선택하면 이곳에서 예약과 잔여 인원을 확인할 수 있습니다.</p></div>';
  if(!weekReady())return '<div class="detail">시간표 데이터를 불러오는 중입니다.</div>';
  if(state.slotReservation)return `<div class="slot-back">${btn('‹ 시간대로 돌아가기','slot-back','ghost')}</div>${detail(state.slotReservation)}`;
  const {day,minute}=state.selectedSlot,c=slotCapacity(state.store,state.rows,state.blocks,day,minute);
  return `<div class="detail"><h2>시간대 상세</h2><p><strong>${dateTitle(day)} · ${minuteLabel(minute)} – ${minuteLabel(minute+30)}</strong></p><div class="slot-summary ${c.past?'past':c.level}"><strong>${c.reason}</strong><span>예약 ${c.used}명 / 정원 ${state.store.capacity}명 · 추가 가능 ${c.remaining}명</span></div>${c.reservations.length?c.reservations.map(r=>`<div class="schedule-item"><div class="schedule-copy"><strong>${h(r.booker_name)}</strong><small>${h(r.booker_affiliation||'소속·단체 없음')}</small><small>${minuteLabel(r.start_minute)} – ${minuteLabel(r.start_minute+r.slot_count*30)} · ${r.people}명</small></div>${btn('상세','slot-reservation','ghost',`data-id="${h(r.id)}"`)}</div>`).join(''):'<p class="muted small">이 시간에 확정된 예약이 없습니다.</p>'}<p class="form-note">30분 한 칸의 현황입니다. 연속 이용 시간 전체의 예약 가능 여부는 등록 시 확인합니다.</p></div>`;
}
function slotDetail(day,minute){if(!weekReady())return;state.selectedSlot={day,minute};state.slotReservation=null;document.querySelector('#slot-panel').innerHTML=slotPanel();document.querySelectorAll('.time-slot').forEach(el=>el.classList.toggle('slot-selected',el.dataset.day===day&&Number(el.dataset.minute)===minute));if(matchMedia('(max-width:930px)').matches)document.querySelector('#slot-panel').scrollIntoView({behavior:'smooth',block:'start'});}
function pageContent(){
  if(state.page==='settings')return settings();
  if(state.page==='dashboard'){const rows=visibleRows(),people=rows.reduce((n,r)=>n+r.people,0);return `<div class="dashboard-switch"><div class="view-tabs">${btn('일별','scope-today',state.scope==='today'?'active':'')}${btn('주간','scope-week',state.scope==='week'?'active':'')}</div><span class="muted small">${state.scope==='today'?dateTitle(state.day):`${dateTitle(weekDays(state.day)[0])} – ${dateTitle(weekDays(state.day)[6])}`} · 확정 예약만 표시</span></div><section class="metrics dashboard-metrics"><div class="metric"><div><label>확정 예약</label><strong>${rows.length}<span>건</span></strong></div></div><div class="metric"><div><label>확정 방문 인원</label><strong>${people}<span>명</span></strong></div></div></section><div class="main-grid"><div><section class="panel"><div class="panel-top"><h2>${state.scope==='today'?'일별':'주간'} 확정 예약</h2>${searchField()}</div><div class="toolbar confirmed-toolbar"><div class="date-nav">${btn('‹','confirmed-prev','','aria-label="이전 날 확정 예약"')}<strong class="confirmed-date" aria-live="polite">${state.day.slice(0,4)}년 ${dateTitle(state.day)}</strong>${btn('›','confirmed-next','','aria-label="다음 날 확정 예약"')}${btn('오늘','confirmed-today','small')}</div><span class="small muted">화살표로 날짜별 확정 예약을 확인하세요.</span></div><div id="reservation-table">${table()}</div></section></div><aside class="panel desktop-detail">${detail()}</aside></div>`;}
  if(state.page==='reservations')return `<div class="main-grid"><div><section class="panel"><div class="panel-top"><h2>승인 대기 요청 <span class="tag pending">${visibleRows().length}건</span></h2>${searchField()}</div><div class="request-note">방문 날짜와 관계없이 아직 처리하지 않은 요청을 최신 접수순으로 표시합니다.</div><div id="reservation-table">${table()}</div></section></div><aside class="panel desktop-detail">${detail()}</aside></div><div class="main-grid requests-timetable">${timetable()}<aside id="slot-panel" class="panel slot-panel" aria-label="시간대 상세" aria-live="polite">${slotPanel()}</aside></div>`;
  return `<div class="main-grid"><div><section class="panel"><div class="panel-top"><h2>${monthTitle()}</h2><div class="date-nav">${btn('‹','prev','','aria-label="이전 달"')}<input id="selected-date" type="month" value="${state.month}" aria-label="조회 월">${btn('›','next','','aria-label="다음 달"')}${btn('오늘','today','small')}</div></div><div class="toolbar"><span class="small muted">날짜를 선택해 예약과 매장 일정을 확인하세요.</span><div class="filters"><select id="filter" aria-label="예약 상태 필터">${[['all','전체 상태'],...Object.entries(statusNames)].map(([v,l])=>`<option value="${v}" ${state.filter===v?'selected':''}>${l}</option>`).join('')}</select>${searchField()}</div></div>${calendar()}<div id="reservation-table">${table()}</div></section>${schedules()}</div><aside class="panel desktop-detail">${detail()}</aside></div>`;
}
function render(){document.documentElement.classList.toggle('large',state.large);if(!state.user&&!state.demo){login();return;}if(!state.store){root.innerHTML=`<div class="boot">${brand()}<h1 style="margin-top:30px">${state.loading?'매장을 불러오는 중입니다':'매장 정보를 확인해주세요'}</h1><p>${h(state.error||'Connect 앱에서 점주 가입과 매장 등록을 먼저 완료해주세요.')}</p>${btn('다시 불러오기','refresh')}${btn('로그아웃','logout','ghost')}</div>`;return;}
  if(state.selected&&!visibleRows().some(r=>r.id===state.selected))state.selected=null;
  const headings={dashboard:['OWNER DASHBOARD','우리 매장의 확정 예약','날짜별 확정 예약과 방문 인원을 확인하세요.'],reservations:['RESERVATION REQUESTS','새로 들어온 예약 요청','예약 요청과 주간 빈 시간을 함께 확인하세요.'],calendar:['MONTHLY CALENDAR','월간 달력','한 달의 예약과 매장 일정을 확인하세요.'],settings:['STORE SETTINGS','매장 설정','매장에 맞게 예약 운영 방식을 설정하세요.']},head=headings[state.page];
  root.innerHTML=`<header class="topbar"><div class="inline">${brand()}<span class="store-name">${h(state.store.name)}</span></div><div class="top-actions">${themeButton()}${btn(state.large?'기본 글씨':'큰 글씨','font','ghost')}<span class="avatar">점주</span>${btn(state.demo?'체험 끝내기':'로그아웃','logout','ghost')}</div></header><div class="layout"><nav class="sidebar" aria-label="주 메뉴"><div class="nav-caption">WORKSPACE</div>${[['dashboard','layout','대시보드'],['reservations','inbox','예약 관리'],['calendar','calendar','월간 달력'],['settings','settings','매장 설정']].map(([page,ic,label])=>btn(`${icon(ic)} ${label}`,'nav-'+page,`nav-button ${state.page===page?'active':''}`,state.page===page?'aria-current="page"':'')).join('')}<div class="sidebar-note">예약에 쓰던 시간을,<br>손님에게.<br><br>Connect for owners</div></nav><main class="workspace"><div class="heading"><div><p class="eyebrow">${head[0]}</p><h1>${head[1]}</h1><p>${head[2]}</p></div>${['dashboard','calendar'].includes(state.page)?btn('＋ 예약 등록','new-reservation','primary'):''}</div>${state.demo?`<div class="notice"><span><strong>샘플 체험 중</strong> · 가상 데이터입니다. 변경 내용은 새로고침하면 초기화됩니다.</span>${btn('실제 로그인','logout','ghost')}</div>`:''}${state.error?`<div class="notice error" role="alert"><span>${h(state.error)}</span>${btn('다시 새로고침','refresh','ghost')}</div>`:''}${!state.store.approved?'<div class="notice">매장 승인 대기 중입니다. 앱 공개와 예약 접수는 관리자 승인 후 가능합니다.</div>':''}${pageContent()}<footer class="sync-footer"><span><i class="sync-dot"></i>${state.demo?'샘플 데이터':state.lastSync?`마지막 갱신 ${state.lastSync} · 5초마다 자동 확인`:'서버 연결 확인 중'}</span>${btn('↻ 새로고침','refresh','ghost small','style="min-height:0;padding:0"')}</footer></main></div>`;
}
async function rpc(name,args){const {data,error}=await db.rpc(name,args);if(error)throw error;return data;}
async function fetchAll(table,store,first,next){let result=[];for(let from=0;;from+=500){const {data,error}=await db.from(table).select('*').eq('store_id',store).gte('service_date',first).lt('service_date',next).order('service_date').order(table==='time_blocks'?'start_minute':'id').range(from,from+499);if(error)throw error;result.push(...data);if(data.length<500)return result;}}
async function fetchPending(store){const result=[];for(let from=0;;from+=500){const {data,error}=await db.from('reservations').select('*').eq('store_id',store).eq('status','pending').order('created_at',{ascending:false}).order('id').range(from,from+499);if(error)throw error;result.push(...data);if(data.length<500)return result;}}
async function refresh(){if(state.demo||!state.user)return;if(state.loading){pendingRefresh=true;return;}state.loading=true;const epoch=state.epoch,user=state.user.id,month=state.month,day=state.day;try{
if(!state.store){const p=await db.from('profiles').select('role').eq('id',user).maybeSingle();if(p.error)throw p.error;if(p.data?.role!=='owner')throw Error('점주 계정으로 로그인해주세요. 예약자 계정은 이용할 수 없습니다.');const s=await db.from('stores').select('*').eq('owner_id',user).order('created_at').limit(1);if(s.error)throw s.error;if(!s.data.length)throw Error('등록된 매장이 없습니다. Connect 앱에서 매장을 등록해주세요.');if(epoch!==state.epoch)return;state.store=s.data[0];}
else {const s=await db.from('stores').select('*').eq('id',state.store.id).eq('owner_id',user).single();if(s.error)throw s.error;if(epoch!==state.epoch)return;state.store=s.data;}
const cells=monthCells(month),week=weekDays(day),first=[addDays(cells[0],-1),addDays(week[0],-1),addDays(today(),-1)].sort()[0],next=[addDays(cells.at(-1),2),addDays(week[6],2),addDays(today(),2)].sort().at(-1),id=state.store.id;
const [rows,blocks,eventResult,pending]=await Promise.all([fetchAll('reservations',id,first,next),fetchAll('time_blocks',id,first,next),fetchAll('owner_schedule_events',id,first,next).then(data=>({data})).catch(error=>({error})),fetchPending(id)]);
if(epoch!==state.epoch||month!==state.month||day!==state.day)return;
state.rows=[...new Map([...rows.filter(r=>r.status!=='pending'),...pending].map(r=>[r.id,r])).values()];state.loadedRange={first,next};state.blocks=blocks;state.events=eventResult.data||[];state.eventError=eventResult.error?'내부 일정을 불러오지 못했습니다. 다시 새로고침해주세요.':'';state.error='';state.loaded=true;state.lastSync=new Intl.DateTimeFormat('ko-KR',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'Asia/Seoul'}).format(new Date());
}catch(e){if(epoch===state.epoch)state.error=message(e);}finally{state.loading=false;if(epoch===state.epoch&&!modal.open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)&&state.page!=='settings')render();if(pendingRefresh){pendingRefresh=false;queueMicrotask(refresh);}}}
function timeOptions(selected,start=0,end=1770){return Array.from({length:Math.floor((end-start)/30)+1},(_,i)=>start+i*30).map(n=>`<option value="${n}" ${n===selected?'selected':''}>${minuteLabel(n)}</option>`).join('');}
function openModal(title,body){modal.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2>${btn('×','close','ghost','aria-label="닫기"')}</div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
const formButtons=(text='저장')=>`<p class="form-error" role="alert"></p><div class="modal-footer">${btn('취소','close','', 'type="button"')}<button class="primary">${text}</button></div>`;
function reservationForm(){requestKey=crypto.randomUUID();lastPayload='';openModal('수동 예약 등록',`<form id="reservation-form"><p class="form-note">전화·문자로 받은 예약을 확정 상태로 등록합니다.</p><label class="field">대표 예약자명 (필수)<input name="name" required maxlength="80" autocomplete="name" placeholder="예: 김민준"></label><label class="field">소속 / 단체명 (선택)<input name="affiliation" maxlength="160" placeholder="예: 경영학과 학생회"></label><div class="form-grid"><label class="field">영업일<input name="date" type="date" value="${state.day}" min="${today()}" required></label><label class="field">인원<input name="people" type="number" min="1" max="${state.store.capacity}" value="2" required></label><label class="field">시작 시간<select name="start">${timeOptions(state.store.opening_minute,state.store.opening_minute,state.store.closing_minute-30)}</select></label><label class="field">이용 시간<select name="slots">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${n===3?'selected':''}>${n*30}분</option>`).join('')}</select></label></div><label class="field">예약 목적 / 메모<input name="purpose" maxlength="30" placeholder="예: 동아리 회식"></label><p class="form-note">‘다음 날’ 시간은 선택한 영업일에 포함됩니다. 정원과 차단 여부는 저장 시 확인합니다.</p>${formButtons('예약 등록')}</form>`);}
function eventForm(id){const e=state.events.find(e=>e.id===id);openModal(e?'매장 일정 수정':'매장 일정 추가',`<form id="event-form" data-id="${h(id||'')}"><p class="form-note">내부 공유용 일정입니다. 예약 접수를 막으려면 별도의 ‘시간 차단’을 이용하세요.</p><label class="field">일정 제목<input name="title" value="${h(e?.title||'')}" maxlength="80" required placeholder="예: 식자재 입고"></label><label class="field">날짜<input type="date" name="date" value="${e?.service_date||state.day}" required></label><label class="check-label"><input type="checkbox" name="allDay" ${e?.start_minute==null?'checked':''}>종일 일정</label><div class="form-grid"><label class="field">시작<select name="start">${timeOptions(e?.start_minute??960)}</select></label><label class="field">종료<select name="end">${timeOptions(e?.end_minute??990,30,1800)}</select></label></div><label class="field">메모<textarea name="memo" maxlength="1000" placeholder="일정에 필요한 메모">${h(e?.memo||'')}</textarea></label>${e?btn('일정 삭제','delete-event','danger','type="button" data-id="'+h(e.id)+'"'):''}${formButtons()}</form>`);toggleAllDay();}
function toggleAllDay(){const form=document.querySelector('#event-form');if(form)for(const n of ['start','end'])form.elements[n].disabled=form.elements.allDay.checked;}
async function blockForm(){openModal('예약 시간 차단','<p class="muted">시간별 예약 가능 여부를 확인하고 있습니다…</p>');const day=state.day;try{const slots=state.demo?Array.from({length:(state.store.closing_minute-state.store.opening_minute)/30},(_,i)=>{const start=state.store.opening_minute+i*30;return {start_minute:start,blocked:state.blocks.some(b=>b.service_date===day&&b.start_minute===start),remaining_seats:state.store.capacity};}):await rpc('get_availability',{p_store_id:state.store.id,p_service_date:day});if(!modal.open)return;openModal('예약 시간 차단',`<form id="blocks-form" data-day="${day}"><p class="form-note">${dateTitle(day)} · 체크한 시간은 앱에서도 예약을 받지 않습니다. 확정 예약과 겹치는 시간은 차단할 수 없습니다.</p><div class="slots">${slots.map(s=>{const occupied=state.rows.some(r=>r.service_date===day&&r.status==='confirmed'&&r.start_minute<s.start_minute+30&&r.start_minute+r.slot_count*30>s.start_minute);return `<label class="slot"><input name="slot" type="checkbox" value="${s.start_minute}" ${s.blocked?'checked':''} ${occupied&&!s.blocked?'disabled':''}>${minuteLabel(s.start_minute)}${occupied?' · 예약':''}</label>`;}).join('')}</div>${formButtons('차단 시간 저장')}</form>`);}catch(e){openModal('예약 시간 차단',`<p class="form-error" role="alert">${h(message(e))}</p>`);}}
async function actionWrite(work,success){if(state.busy)return;state.busy=true;const buttons=[...modal.querySelectorAll('button'),...document.querySelectorAll('.detail-actions button')];buttons.forEach(b=>b.disabled=true);try{await work();if(modal.open)modal.close();await refresh();render();toast(success);}catch(e){const el=modal.open?modal.querySelector('.form-error'):null;if(el)el.textContent=message(e);else{state.error=message(e);render();}}finally{state.busy=false;buttons.forEach(b=>b.disabled=false);if(!modal.open)render();}}
async function decide(id,action){const r=state.rows.find(r=>r.id===id);if(!r)return;const next={accept:'confirmed',reject:'rejected',cancel:'cancelled',complete:'completed'}[action];await actionWrite(async()=>{if(state.demo){r.status=next;return;}const names={accept:'decide_reservation',reject:'decide_reservation',cancel:'cancel_reservation',complete:'complete_reservation'};await rpc(names[action],{p_reservation_id:id,...(['accept','reject'].includes(action)?{p_accept:action==='accept'}:{})});},`예약을 ${statusNames[next]} 처리했습니다.`);}
async function logout(){if(state.busy)return;if(!state.demo&&db){const {error}=await db.auth.signOut({scope:'local'});if(error){toast(message(error));return;}}state.epoch++;state.selectedSlot=null;state.slotReservation=null;Object.assign(state,{demo:false,user:null,store:null,rows:[],events:[],blocks:[],error:'',eventError:'',selected:null,loaded:false,loadedRange:null,lastSync:null});if(modal.open)modal.close();authSent=false;authError='';render();}
root.addEventListener('input',e=>{if(e.target.id==='search'){state.query=e.target.value;document.querySelector('#reservation-table').innerHTML=table();}});
document.addEventListener('change',e=>{if(e.target.name==='allDay')toggleAllDay();if(e.target.id==='filter'){state.filter=e.target.value;document.querySelector('#reservation-table').innerHTML=table();}if(e.target.id==='selected-date'&&e.target.value){if(state.view==='calendar'){state.month=e.target.value;state.day=state.month+'-01';}else{state.day=e.target.value;state.month=state.day.slice(0,7);}state.selected=null;render();refresh();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.closest('form'))e.preventDefault();const a=b.dataset.action;if(a.startsWith('confirmed-')){state.day=a==='confirmed-today'?today():addDays(state.day,a==='confirmed-prev'?-1:1);state.month=state.day.slice(0,7);state.scope='today';state.selected=null;state.query='';render();refresh();return;}if(a==='slot-detail'){slotDetail(b.dataset.day,Number(b.dataset.minute));return;}if(a==='slot-reservation'){state.slotReservation=b.dataset.id;document.querySelector('#slot-panel').innerHTML=slotPanel();return;}if(a==='slot-back'){state.slotReservation=null;document.querySelector('#slot-panel').innerHTML=slotPanel();return;}if(a==='scope-today'||a==='scope-week'){state.scope=a==='scope-today'?'today':'week';if(state.scope==='today'){state.day=today();state.month=state.day.slice(0,7);}state.selected=null;render();refresh();return;}if(a.startsWith('week-')){state.selectedSlot=null;state.slotReservation=null;state.day=a==='week-today'?today():addDays(state.day,a==='week-prev'?-7:7);state.month=state.day.slice(0,7);state.selected=null;render();refresh();return;}if(a==='theme'){window.connectTheme.toggle();return;}if(a==='close'){if(!state.busy)modal.close();return;}if(a==='demo'){state.epoch++;state.selectedSlot=null;state.slotReservation=null;Object.assign(state,sampleData(),{demo:true,user:null,loaded:true,error:'',day:today(),month:today().slice(0,7),page:'dashboard',selected:null,scope:'today'});render();return;}if(a==='logout'){await logout();return;}if(a==='auth-reset'){if(Date.now()<resendAfter){authError='인증번호는 60초 후 다시 요청할 수 있습니다.';login();return;}authSent=false;authError='';login();return;}if(a==='refresh'){await refresh();render();return;}if(a==='font'){state.large=!state.large;render();return;}if(a==='new-reservation'){reservationForm();return;}if(a==='new-event'||a==='edit-event'){eventForm(b.dataset.id);return;}if(a==='blocks'){await blockForm();return;}if(a==='select'){state.selected=b.dataset.id;render();if(matchMedia('(max-width:930px)').matches)openModal('예약 상세',detail());return;}if(['accept','reject','cancel','complete'].includes(a)){if(['reject','cancel'].includes(a)){openModal(a==='reject'?'예약을 거절할까요?':'예약을 취소할까요?',`<p>처리 결과가 Connect 앱에도 반영됩니다.</p><p class="form-error" role="alert"></p><div class="modal-footer">${btn('돌아가기','close')}${btn(a==='reject'?'거절하기':'취소하기','confirm-status','danger',`data-kind="${a}" data-id="${h(b.dataset.id)}"`)}</div>`);}else await decide(b.dataset.id,a);return;}if(a==='confirm-status'){await decide(b.dataset.id,b.dataset.kind);return;}if(a==='delete-event'){const id=b.dataset.id;openModal('일정을 삭제할까요?',`<p>이 일정의 제목과 메모가 삭제됩니다.</p><p class="form-error" role="alert"></p><div class="modal-footer">${btn('돌아가기','close')}${btn('삭제하기','confirm-delete-event','danger',`data-id="${h(id)}"`)}</div>`);return;}if(a==='confirm-delete-event'){await actionWrite(async()=>{if(state.demo){state.events=state.events.filter(x=>x.id!==b.dataset.id);return;}const {error}=await db.from('owner_schedule_events').delete().eq('id',b.dataset.id).eq('store_id',state.store.id);if(error)throw error;},'일정을 삭제했습니다.');return;}
if(a.startsWith('nav-')){state.page=a.slice(4);state.view=state.page==='calendar'?'calendar':'ledger';state.query='';state.filter='all';state.selected=null;render();refresh();return;}if(a==='day'){state.day=b.dataset.day;state.selected=null;}if(a==='today'){state.day=today();state.month=state.day.slice(0,7);state.selected=null;}if(a==='prev'||a==='next'){const n=a==='prev'?-1:1;if(state.view==='calendar'){state.month=moveMonth(state.month,n);state.day=state.month+'-01';}else{state.day=addDays(state.day,n);state.month=state.day.slice(0,7);}state.selected=null;}render();if(['prev','next','today'].includes(a))refresh();});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,fd=new FormData(form),v=n=>String(fd.get(n)||'');if(form.id==='login-form'){if(authBusy||!db)return;authBusy=true;authError='';const email=v('email').trim().toLowerCase(),token=v('token');authEmail=email;login();try{if(authSent){const {error}=await db.auth.verifyOtp({email,token,type:'email'});if(error)throw error;}else{const {error}=await db.auth.signInWithOtp({email,options:{shouldCreateUser:false}});if(error)throw error;authSent=true;resendAfter=Date.now()+60000;}}catch(err){authError=message(err);}finally{authBusy=false;if(!state.user)login();}return;}
if(form.id==='reservation-form'){const payload={p_store_id:state.store.id,p_service_date:v('date'),p_start_minute:Number(v('start')),p_slot_count:Number(v('slots')),p_people:Number(v('people')),p_booker_name:v('name').trim(),p_booker_affiliation:v('affiliation').trim(),p_event_purpose:v('purpose').trim()};await actionWrite(async()=>{if(!payload.p_booker_name)throw Error('대표 예약자명을 입력해주세요.');if(payload.p_start_minute+payload.p_slot_count*30>state.store.closing_minute)throw Error('종료 시간이 영업 종료를 넘습니다. 이용 시간을 줄여주세요.');const signature=JSON.stringify(payload);if(lastPayload&&signature!==lastPayload)requestKey=crypto.randomUUID();lastPayload=signature;if(state.demo){state.rows.push({id:crypto.randomUUID(),store_id:state.store.id,service_date:payload.p_service_date,start_minute:payload.p_start_minute,slot_count:payload.p_slot_count,people:payload.p_people,booker_name:payload.p_booker_name,booker_affiliation:payload.p_booker_affiliation,event_purpose:payload.p_event_purpose,is_manual:true,status:'confirmed',starts_at:isoAt(payload.p_service_date,payload.p_start_minute),ends_at:isoAt(payload.p_service_date,payload.p_start_minute+payload.p_slot_count*30)});}else await rpc('create_manual_reservation',{...payload,p_request_id:requestKey});state.day=payload.p_service_date;state.month=state.day.slice(0,7);state.page='dashboard';state.scope=state.day===today()?'today':'week';},'예약을 등록했습니다.');}
if(form.id==='event-form'){const all=fd.has('allDay'),payload={store_id:state.store.id,title:v('title').trim(),service_date:v('date'),start_minute:all?null:Number(v('start')),end_minute:all?null:Number(v('end')),memo:v('memo').trim()};await actionWrite(async()=>{if(!payload.title)throw Error('일정 제목을 입력해주세요.');if(!all&&payload.end_minute<=payload.start_minute)throw Error('종료 시간은 시작 시간보다 늦어야 합니다.');const id=form.dataset.id||form.dataset.requestId||(form.dataset.requestId=crypto.randomUUID());if(state.demo){state.events=state.events.filter(x=>x.id!==id);state.events.push({id,...payload});}else{const query=form.dataset.id?db.from('owner_schedule_events').update(payload).eq('id',id).eq('store_id',state.store.id):db.from('owner_schedule_events').upsert({id,...payload},{onConflict:'id'});const {error}=await query.select('id').single();if(error)throw error;}state.day=payload.service_date;state.month=state.day.slice(0,7);},'매장 일정을 저장했습니다.');}
if(form.id==='blocks-form')await actionWrite(async()=>{const day=form.dataset.day,mins=fd.getAll('slot').map(Number);if(state.demo){state.blocks=state.blocks.filter(b=>b.service_date!==day);state.blocks.push(...mins.map(start_minute=>({service_date:day,start_minute})));}else await rpc('replace_time_blocks',{p_store_id:state.store.id,p_service_date:day,p_start_minutes:mins});},'예약 차단 시간을 저장했습니다.');
if(form.id==='settings-form')await actionWrite(async()=>{const payload={p_store_id:state.store.id,p_capacity:Number(v('capacity')),p_opening_minute:Number(v('opening')),p_closing_minute:Number(v('closing')),p_allow_shared:fd.has('shared')};if(payload.p_closing_minute<=payload.p_opening_minute)throw Error('영업 종료는 시작 시간보다 늦어야 합니다.');if(state.demo)Object.assign(state.store,{capacity:payload.p_capacity,opening_minute:payload.p_opening_minute,closing_minute:payload.p_closing_minute,allow_shared:payload.p_allow_shared});else state.store=await rpc('update_store_capacity',payload);},'매장 설정을 저장했습니다.');});
modal.addEventListener('cancel',e=>{if(state.busy)e.preventDefault();});modal.addEventListener('close',()=>{if(!state.busy)render();});
window.addEventListener('online',()=>refresh());window.addEventListener('offline',()=>{if(!state.demo&&state.user){state.error='오프라인 상태입니다. 인터넷에 연결되면 다시 갱신합니다.';if(!modal.open)render();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});setInterval(()=>{if(!document.hidden&&!state.busy)refresh();},5000);
if(db)db.auth.onAuthStateChange((_event,session)=>{if(state.demo)return;const next=session?.user||null;if(next?.id===state.user?.id)return;state.epoch++;state.selectedSlot=null;state.slotReservation=null;Object.assign(state,{user:next,store:null,rows:[],events:[],blocks:[],loaded:false,error:'',selected:null,loadedRange:null,lastSync:null});if(modal.open)modal.close();render();if(next)setTimeout(refresh,0);});
render();
